import{_ as i,l as r,o as e,c as l,v as t,p as S,x as s,d as T,i as c,S as n}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"TCP 状态机","description":"","frontmatter":{"title":"TCP 状态机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-state-machine.md","filePath":"cs/tcp-state-machine.md","lastUpdated":1789023840000}'),p={name:"cs/tcp-state-machine.md"};function E(d,a,h,I,_,A){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="tcp-状态机" tabindex="-1">TCP 状态机 <a class="header-anchor" href="#tcp-状态机" aria-label="Permalink to &quot;TCP 状态机&quot;">​</a></h1><div class="epigraph"><p>连接是状态机：LISTEN、握手三态、ESTABLISHED、四次挥手各态；错误的迁移比错一个 cwnd 更容易把套接字卡死。</p><footer>—— 据 RFC 9293 第 3.3 节；Stevens, TCP/IP Illustrated 状态图整理</footer></div><p>主干<a href="/cs/tcp-handshake">三次握手</a> 与 <a href="/cs/tcp-time-wait">TIME_WAIT</a> 已拆过。<a href="/cs/mss-clamping">上一课</a> 发生在 SYN 上。缺口是<strong>整图</strong>：11 个状态怎么迁，ABORT vs 优雅关。本课不把 SYN cookie 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>应用看 ESTABLISHED 与 close。内核还要 SYN-SENT、SYN-RECEIVED、FIN-WAIT-1/2、CLOSING、CLOSE-WAIT、LAST-ACK、TIME_WAIT。同时打开、同时关闭是边角。RST 从多数态回到 CLOSED。半开：一边已关或崩溃，另一边还 ESTABLISHED——保活后课。窗口缩放只在 SYN 协商，状态错了不能补选项。</p><p>不要把状态机写成拥塞控制；cwnd 是 ESTABLISHED 里的变量。</p><p><span class="marginnote">RFC 9293 图 5。本课不把每条错误迁移画成考试填空，只钉主路径与 TIME_WAIT 理由（已在主干）。</span></p><h3 id="拥塞变量栖在-established" tabindex="-1">拥塞变量栖在 ESTABLISHED <a class="header-anchor" href="#拥塞变量栖在-established" aria-label="Permalink to &quot;拥塞变量栖在 ESTABLISHED&quot;">​</a></h3><p>应用 close 不等于 CLOSED。RST 中止；TIME_WAIT 防旧段。同时打开是规范允许的边角。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画主路径：LISTEN → SYN-RCVD → EST → 主动关 FIN-WAIT → TIME_WAIT。对照 QUIC：连接 ID 迁移后课，状态更少暴露。</p>',11)),(e(),S(n,null,{default:s(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LI%5B%22LISTEN%22%5D%20--%3E%20SR%5B%22SYN-RECEIVED%22%5D%0A%20%20SR%20--%3E%20ES%5B%22ESTABLISHED%22%5D%0A%20%20ES%20--%3E%20FW%5B%22FIN-WAIT%22%5D%0A%20%20FW%20--%3E%20TW%5B%22TIME_WAIT%22%5D%0A%20%20ES%20--%3E%20RST%5B%22RST%20%E5%88%B0%20CLOSED%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[T(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SYN 泛洪把 SYN-RCVD 队列填满，下一课 cookies。LACP 与路由变化不改状态机，只改路径。抓包排障：看标志位对状态，比看窗口更先。incast 不改状态，只改拥塞变量。</p><p>同时打开：双方 SYN-SENT → SYN-RCVD → EST，序号交叉，规范允许。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TCP 快速打开的全部 cookie。SYN cookies 是下一课。后课默认：套接字生命周期 = 这份状态机；应用 close 不等于立刻 CLOSED。</p><p>把 TIME_WAIT 当泄漏而全局关，会制造旧段串连接。</p><p>上一课留下的缺口在本课收口；「TCP 状态机」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/syn-cookies">SYN cookies</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主路径：听、握、传、挥、TIME_WAIT。</li><li>RST 中止；半开留给保活课。</li><li>拥塞变量栖在 ESTABLISHED。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；Stevens。</li></ul>',10))])}const D=i(p,[["render",E]]);export{C as __pageData,D as default};
